    {
      "label": "A",
      "phrases": [
        {
          "id": "O1-01",
          "zh": "这样的日子我已经受够"
        },
        {
          "id": "O1-02",
          "zh": "永远这种东西根本不存在"
        },
        {
          "id": "O1-03",
          "zh": "在终结来临之前"
        },
        {
          "id": "O1-04",
          "zh": "试着迈出一步"
        },
        {
          "id": "O1-05",
          "zh": "一边接纳着"
        },
        {
          "id": "O1-06",
          "zh": "一边祈祷着"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "O1-01",
          "zh": "受够 一个人 熬到天亮"
        },
        {
          "id": "O1-02",
          "zh": "哪里有什么 永远 可以等"
        },
        {
          "id": "O1-03",
          "zh": "在一切慢慢 结束之前"
        },
        {
          "id": "O1-04",
          "zh": "还是 试着迈出一步"
        },
        {
          "id": "O1-05",
          "zh": "一边接受一切"
        },
        {
          "id": "O1-06",
          "zh": "一边悄悄祈祷"
        }
      ]
    }
  ]
}

